	/** 
	 * jumpstart the process by instantiating2 DataSource
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		dataSourceId = DataSourceService.getDataSourceInstance()
		.createDataSource( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		DataSourceService.getDataSourceInstance()
				.createDataSource( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.dataSourceSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for DataSource : " + successValue.getDataSourceId());
							  if (successValue.getDataSourceId().equals(dataSourceId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfDataSourceList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("DataSource test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on dataSource consumed")
					);
			subscriber.dataSourceSubscribe( dataSourceId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for DataSource : " + successValue.getDataSourceId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfDataSourceList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on dataSource for dataSourceId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a DataSource. 
	 */
	protected DataSource read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created DataSource" );

		DataSource entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read DataSource with primary key" );
		msg.append( dataSourceId );
		
		DataSourceFetchOneSummary fetchOneSummary = new DataSourceFetchOneSummary( dataSourceId );

		try {
			entity = DataSourceService.getDataSourceInstance().getDataSource( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found DataSource " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a DataSource.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a DataSource." );

		StringBuilder msg = new StringBuilder( "Failed to update a DataSource : " );        
		DataSource entity = read();
		UpdateDataSourceCommand command = generateUpdateCommand();
		command.setDataSourceId(entity.getDataSourceId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created DataSource." );

			// for use later on...
			dataSourceId = entity.getDataSourceId();

			DataSourceService proxy = DataSourceService.getDataSourceInstance();  

			proxy.updateDataSource( command ).get();

			LOGGER.info( "-- Successfully saved DataSource - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + dataSourceId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a DataSource.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created DataSource." );

		DataSource entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read DataSource with id " + dataSourceId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read DataSource with id " + dataSourceId );

			throw e;
		}

		try{
			DataSourceService.getDataSourceInstance().delete( new DeleteDataSourceCommand( entity.getDataSourceId() ) ).get();
			LOGGER.info( "-- Successfully deleted DataSource with id " + dataSourceId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete DataSource with id " + dataSourceId );

			throw e;
		}
	}

	/**
	 * get all DataSources.
	 */
	protected List<DataSource> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of DataSources:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all DataSource : " );        
		List<DataSource> collection  = new ArrayList<>();

		try {
			// call the static get method on the DataSourceService
			collection = DataSourceService.getDataSourceInstance().getAllDataSource();
			assertNotNull( collection, "An Empty collection of DataSource was incorrectly returned.");
			
			// Now print out the values
			DataSource entity = null;            
			Iterator<DataSource> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getDataSourceId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

